int[] memo;                                   // memo[k] == 0 — not computed yet
int Climb(int k) {
    if (k <= 1) return 1;
    if (memo[k] != 0) return memo[k];
    return memo[k] = Climb(k - 1) + Climb(k - 2);
}
// call: memo = new int[n + 1]; Climb(n);

