public int ClimbStairs(int n) {
    int prev = 1, cur = 1;                 // ways[i − 2], ways[i − 1]
    for (int i = 2; i <= n; i++)
        (prev, cur) = (cur, prev + cur);   // slide the window one step
    return cur;
}

