// a 3 × 4 grid: dp[r, c] = above + left
// 1  1  1  1
// 1  2  3  4
// 1  3  6 10   → 10 paths = C(5, 2)
long Paths(int m, int n) {                    // the formula: C(m + n − 2, k)
    int k = Math.Min(m, n) - 1, total = m + n - 2;
    long res = 1;
    for (int i = 1; i <= k; i++) res = res * (total - k + i) / i;  // divides exactly
    return res;
}

